    my_y = observation.get('my_position', (0, 0))[1]
    resources = observation.get('resources', [])
    enemies = observation.get('enemy_positions', [])
    territory_points = observation.get('territory_control_points', [])

    def move_toward(target):
        dx = 0
        dy = 0
        if target[0] > my_x:
            dx = 1
        elif target[0] < my_x:
            dx = -1
